"use client";

import { useEffect, useState } from "react";
import AuthGate from "@/components/auth-gate";
import { api } from "@/lib/api";
import { Spinner } from "@/components/ui/spinner";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";

interface Address {
  id: string;
  label: string;
  recipientName: string;
  line1: string;
  line2: string | null;
  city: string;
  region: string | null;
  postalCode: string | null;
  countryCode: string;
  phone: string | null;
  isDefault: boolean;
}

function AddressesPage() {
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await api<Address[]>("/addresses");
        setAddresses(res.data || []);
      } catch (e) {
      } finally {
        setLoading(false);
      }
    };
    void load();
  }, []);

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Spinner className="size-6" />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-3xl p-6">
      <div className="mb-6 flex items-center justify-between">
        <h1 className="text-3xl font-bold">Addresses</h1>
        <Button size="sm">Add address</Button>
      </div>
      {addresses.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <p className="text-muted-foreground">No addresses saved yet</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {addresses.map((a) => (
            <Card key={a.id}>
              <CardHeader className="flex flex-row items-center justify-between">
                <div>
                  <CardTitle className="text-lg">{a.recipientName}</CardTitle>
                  <p className="text-sm text-muted-foreground">{a.label}</p>
                </div>
                {a.isDefault && <Badge>Default</Badge>}
              </CardHeader>
              <CardContent className="text-sm text-muted-foreground">
                <p>{a.line1}</p>
                {a.line2 && <p>{a.line2}</p>}
                <p>
                  {[a.city, a.region, a.postalCode, a.countryCode]
                    .filter(Boolean)
                    .join(", ")}
                </p>
                {a.phone && <p>{a.phone}</p>}
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

export default function AddressesRoute() {
  return (
    <AuthGate>
      <AddressesPage />
    </AuthGate>
  );
}
